<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/tasks_helpers.php';
class TaskWorkflowException extends RuntimeException{} final class TaskWorkflowConflict extends TaskWorkflowException{}
/** Official-task state machine. Current timestamps are projections; task_events is the immutable history. */
final class TaskWorkflowService{
 public const STATES=['assigned','acknowledged','in_progress','blocked','submitted','correction_required','completed','cancelled'];
 private const TRANSITIONS=[
  'acknowledge'=>['employee',['assigned'],'acknowledged','employee','acknowledged'],
  'start'=>['employee',['assigned','acknowledged'],'in_progress','employee','started'],
  'block'=>['employee',['acknowledged','in_progress','correction_required'],'blocked','admin','blocker_reported'],
  'blocker_respond'=>['admin',['blocked'],'blocked','admin','blocker_response'],
  'blocker_resolve'=>['admin',['blocked'],'in_progress','employee','blocker_resolved'],
  'correction_resume'=>['employee',['correction_required'],'in_progress','employee','correction_resumed'],
  'submit'=>['employee',['in_progress'],'submitted','admin','submitted'],
  'correction'=>['admin',['submitted'],'correction_required','employee','correction_requested'],
  'approve'=>['admin',['submitted'],'completed','none','approved'],
  'reopen'=>['admin',['completed'],'in_progress','employee','reopened'],
  'cancel'=>['admin',['assigned','acknowledged','in_progress','blocked','submitted','correction_required'],'cancelled','none','cancelled']];
 private array $createdFiles=[]; private array $pendingEventIds=[];
 public function __construct(private PDO $db,private array $actor,private ?string $storageDir=null){canonical_work_initialize_schema($db);$this->storageDir??=dirname(__DIR__).'/storage/task-attachments';}
 private function actorId():int{$id=filter_var($this->actor['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)throw new TaskWorkflowException('Authenticated actor is required.');return $id;}
 private function role():string{$r=(string)($this->actor['role_name']??'');if(!in_array($r,['admin','employee'],true))throw new TaskWorkflowException('Task access is not permitted.');return $r;}
 private function now():string{return (new DateTimeImmutable('now',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d H:i:s');}
 private function task(int $id):array{$s=$this->db->prepare('SELECT * FROM portal_tasks WHERE id=?');$s->execute([$id]);$t=$s->fetch(PDO::FETCH_ASSOC);if(!$t)throw new TaskWorkflowException('Task not found.');return $t;}
 private function authorize(array $t):void{if($this->role()==='employee'&&(int)$t['assignee_id']!==$this->actorId())throw new TaskWorkflowException('You may access only your assigned work.');}
 private function version(int $v):void{if($v<1)throw new TaskWorkflowException('Task version is required; reload before saving.');}
 private function employee(mixed $raw):int{if(is_int($raw))$id=$raw;elseif(is_string($raw)&&preg_match('/^[1-9]\d*$/',$raw))$id=(int)$raw;else throw new TaskWorkflowException('Select a valid active employee.');$s=$this->db->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.status='active' AND r.name='employee'");$s->execute([$id]);if(!$s->fetchColumn())throw new TaskWorkflowException('Select a valid active employee.');return $id;}
 private function date(?string $v,string $label):?string{$v=trim((string)$v);if($v==='')return null;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();if(!$d||($e!==false&&($e['warning_count']||$e['error_count']))||$d->format('Y-m-d')!==$v)throw new TaskWorkflowException("Invalid $label date.");return $v;}
 private function time(?string $v):?string{$v=trim((string)$v);if($v==='')return null;if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$v))throw new TaskWorkflowException('Invalid due time.');return $v;}
 private function legacy(string $s):string{return match($s){'in_progress','submitted'=>'in_progress','completed','cancelled'=>'done',default=>'todo'};}
 private function routing(string $r,array $t):array{return match($r){'employee'=>[(int)$t['assignee_id'],'user',(int)$t['assignee_id'],null],'admin'=>[null,'audience',null,'admin'],default=>[null,'none',null,null]};}
 public static function taskLink(string $role,array $task):string{$role=$role==='admin'?'admin':'employee';$view=(int)($task['archived_flag']??0)?'archived':match((string)($task['workflow_status']??'')){'completed'=>'completed','cancelled'=>'cancelled',default=>'active'};$id=(int)$task['id'];return "$role-tasks.php?view=$view&task=$id#task-$id";}
 /** Notification intent is deliberately independent of the next-action projection. */
 private function recipients(string $type,array $old,array $new):array{$employee=['type'=>'user','user_id'=>(int)$new['assignee_id'],'role'=>'employee'];$admin=['type'=>'audience','audience'=>'admin','role'=>'admin'];return match($type){'assigned','recurrence_created','blocker_response','blocker_resolved','correction_requested','approved','cancelled','reassigned','schedule_priority_revised'=>[$employee],'acknowledged','started','progress','blocker_reported','submitted','resubmitted','correction_resumed'=>[$admin],'reply'=>$this->role()==='employee'?[$admin]:[$employee],'reopened'=>$new['responsibility']==='admin'?[$admin]:[$employee],'proof_uploaded'=>$this->role()==='employee'?[$admin]:[$employee],default=>[]};}
 private function event(array $old,array $new,string $type,array $details=[]):int{$o=$this->occurrence((int)$new['id']);$at=$this->now();$recipients=$this->recipients($type,$old,$new);foreach($recipients as &$recipient){$recipient['deep_link']=self::taskLink((string)$recipient['role'],$new);unset($recipient['role']);}unset($recipient);$payload=['contract_version'=>2,'task_id'=>(int)$new['id'],'canonical_task_id'=>(int)$new['id'],'occurrence_number'=>(int)($o['occurrence_number']??1),'series_id'=>(string)($new['recurrence_series_id']??''),'event_type'=>$type,'actor'=>['id'=>$this->actorId(),'role'=>$this->role()],'old_workflow_state'=>$old['workflow_status']??null,'new_workflow_state'=>$new['workflow_status'],'old_assignee_id'=>isset($old['assignee_id'])?(int)$old['assignee_id']:null,'new_assignee_id'=>(int)$new['assignee_id'],'responsibility'=>$new['responsibility'],'intended_recipients'=>$recipients,'occurred_at'=>$at,'task_version'=>(int)$new['version'],'deep_links'=>array_values(array_unique(array_column($recipients,'deep_link'))),'details'=>$details];$s=$this->db->prepare('INSERT INTO task_events(task_id,actor_id,event_type,event_data,task_version,created_at) VALUES(?,?,?,?,?,?)');$s->execute([(int)$new['id'],$this->actorId(),$type,json_encode($payload,JSON_THROW_ON_ERROR),(int)$new['version'],$at]);$id=(int)$this->db->lastInsertId();$this->pendingEventIds[]=$id;return $id;}
 private function occurrence(int $id):array{$s=$this->db->prepare('SELECT * FROM task_occurrences WHERE task_id=?');$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC)?:[];}
 private function message(int $id,string $type,string $body):?int{if(trim($body)==='')return null;$s=$this->db->prepare('INSERT INTO task_messages(task_id,author_id,body,created_at,message_type) VALUES(?,?,?,?,?)');$s->execute([$id,$this->actorId(),trim($body),$this->now(),$type]);return (int)$this->db->lastInsertId();}
 private function atomic(callable $fn):mixed{$this->createdFiles=[];$this->pendingEventIds=[];$this->db->exec('BEGIN IMMEDIATE');try{$v=$fn();$events=$this->pendingEventIds;$this->db->commit();$this->createdFiles=[];$this->pendingEventIds=[];foreach($events as $eventId){try{task_notification_project_event($this->db,$eventId);}catch(Throwable $e){error_log('Task notification projection failed for event '.(int)$eventId);}}return $v;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();foreach($this->createdFiles as $p)if(is_file($p))@unlink($p);$this->createdFiles=[];$this->pendingEventIds=[];throw $e;}}
 public function allowedActions(array $t):array{if((int)$t['archived_flag'])return [];$out=[];foreach(self::TRANSITIONS as $a=>[$role,$from])if($role===$this->role()&&in_array($t['workflow_status'],$from,true))$out[]=$a;return $out;}
 public function create(array $i,array $files=[]):array{if($this->role()!=='admin')throw new TaskWorkflowException('Only an administrator can assign official work.');foreach(['title','description','expected_outcome'] as $f)if(trim((string)($i[$f]??''))==='')throw new TaskWorkflowException(ucwords(str_replace('_',' ',$f)).' is required.');$a=$this->employee($i['assignee_id']??null);$p=(string)($i['priority']??'medium');if(!in_array($p,['low','medium','high','urgent'],true))throw new TaskWorkflowException('Invalid priority.');$f=(string)($i['frequency_type']??'once');if(!in_array($f,['once','daily','weekly','monthly','custom'],true))throw new TaskWorkflowException('Invalid recurrence.');$n=(int)($i['custom_every_n_days']??0);if($f==='custom'&&$n<1)throw new TaskWorkflowException('Custom recurrence must be at least one day.');$start=$this->date($i['start_date']??null,'start');$due=$this->date($i['due_date']??null,'due');if($start&&$due&&$start>$due)throw new TaskWorkflowException('Start date cannot be after due date.');$time=$this->time($i['due_time']??null);$link=(string)($i['linked_entity_type']??'');if(!in_array($link,['','customer','project','site'],true))throw new TaskWorkflowException('Invalid linked entity type.');return $this->atomic(function()use($i,$files,$a,$p,$f,$n,$start,$due,$time,$link){$now=$this->now();$series=bin2hex(random_bytes(16));$s=$this->db->prepare('INSERT INTO portal_tasks(title,description,status,priority,workflow_priority,assignee_id,created_at,updated_at,assigned_at,expected_outcome,category,linked_entity_type,linked_entity_id,start_date,due_date,due_time,frequency_type,custom_every_n_days,proof_required,workflow_status,responsibility,attention_owner_id,last_activity_at,recurrence_series_id,created_by,official_flag) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)');$s->execute([trim($i['title']),trim($i['description']),'todo',$p==='urgent'?'high':$p,$p,$a,$now,$now,$now,trim($i['expected_outcome']),trim((string)($i['category']??'')),$link?:null,trim((string)($i['linked_entity_id']??''))?:null,$start,$due,$time,$f,$n,!empty($i['proof_required'])?1:0,'assigned','employee',$a,$now,$series,$this->actorId()]);$id=(int)$this->db->lastInsertId();$this->db->prepare('INSERT INTO task_occurrences(task_id,series_id,occurrence_number,scheduled_for,created_at) VALUES(?,?,?,?,?)')->execute([$id,$series,1,$due,$now]);$mid=$this->message($id,'assignment',trim($i['description']));foreach($files as $file)$this->storeAttachment($id,$mid,$file);$new=$this->task($id);$this->event([],$new,'assigned',['proof_required'=>(bool)$new['proof_required']]);return $this->detail($id);});}
 public function transition(int $id,int $v,string $action,string $body=''):array{$this->version($v);if(!isset(self::TRANSITIONS[$action]))throw new TaskWorkflowException('Invalid task action.');[$role,$from,$to,$resp,$type]=self::TRANSITIONS[$action];if($role!==$this->role())throw new TaskWorkflowException('This action is not permitted for your role.');if(in_array($action,['block','blocker_respond','blocker_resolve','submit','correction','reopen','cancel'],true)&&trim($body)==='')throw new TaskWorkflowException('An explanation is required.');return $this->atomic(function()use($id,$v,$action,$body,$from,$to,$resp,$type){$old=$this->task($id);$this->authorize($old);if((int)$old['version']!==$v)throw new TaskWorkflowConflict('Someone updated this task while you were working. Reload it and try again; your text was not saved.');if((int)$old['archived_flag']||!in_array($old['workflow_status'],$from,true))throw new TaskWorkflowException('That action is not available in the current task state.');if($action==='submit'&&(int)$old['proof_required']){$q=$this->db->prepare('SELECT COUNT(*) FROM task_attachments WHERE task_id=?');$q->execute([$id]);if(!(int)$q->fetchColumn())throw new TaskWorkflowException('Proof attachment is required before submission.');}$now=$this->now();[$owner]=$this->routing($resp,$old);$set=['workflow_status'=>$to,'status'=>$this->legacy($to),'responsibility'=>$resp,'attention_owner_id'=>$owner,'updated_at'=>$now,'last_activity_at'=>$now,'version'=>$v+1];if($action==='acknowledge')$set['acknowledged_at']=$now;if($action==='start'&&!$old['acknowledged_at']){$set['acknowledged_at']=$now;$set['started_at']=$now;}elseif(in_array($action,['start','blocker_resolve','correction_resume','reopen'],true))$set['started_at']=$now;if($action==='correction_resume')$set['correction_acknowledged_at']=$now;if($action==='submit'){$set['submitted_at']=$now;$set['submission_summary']=trim($body);}if($action==='approve'){$set+=['approved_at'=>$now,'approved_by'=>$this->actorId(),'completed_at'=>$now,'last_completed_at'=>$now,'cancelled_at'=>null];}if($action==='cancel'){$set['cancelled_at']=$now;$set['closed_reason']=trim($body);}if($action==='reopen')$set+=['submitted_at'=>null,'approved_at'=>null,'approved_by'=>null,'completed_at'=>null,'cancelled_at'=>null,'archived_at'=>null,'archived_flag'=>0,'closed_reason'=>trim($body)];$parts=[];$vals=[];foreach($set as $k=>$x){$parts[]="$k=?";$vals[]=$x;}$vals+=[];$vals[]=$id;$vals[]=$v;$s=$this->db->prepare('UPDATE portal_tasks SET '.implode(',',$parts).' WHERE id=? AND version=?');$s->execute($vals);if($s->rowCount()!==1)throw new TaskWorkflowConflict('Someone updated this task while you were working. Reload it and try again.');$this->message($id,$type,$body);$new=$this->task($id);$eventType=($action==='submit'&&!empty($old['correction_acknowledged_at']))?'resubmitted':$type;$this->event($old,$new,$eventType,['has_explanation'=>trim($body)!=='']);if($action==='approve')$this->next($new,$now);return $this->detail($id);});}
 public function post(int $id,int $v,string $type,string $body):array{$this->version($v);if(!in_array($type,['reply','progress'],true)||trim($body)==='')throw new TaskWorkflowException('Message is required.');return $this->atomic(function()use($id,$v,$type,$body){$old=$this->task($id);$this->authorize($old);if((int)$old['version']!==$v)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');if(in_array($old['workflow_status'],['completed','cancelled'],true)||(int)$old['archived_flag'])throw new TaskWorkflowException('Closed tasks cannot receive messages.');$r=$this->role()==='admin'?'employee':'admin';[$owner]=$this->routing($r,$old);$n=$this->now();$s=$this->db->prepare('UPDATE portal_tasks SET responsibility=?,attention_owner_id=?,version=version+1,updated_at=?,last_activity_at=? WHERE id=? AND version=?');$s->execute([$r,$owner,$n,$n,$id,$v]);if($s->rowCount()!==1)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');$this->message($id,$type,$body);$new=$this->task($id);$this->event($old,$new,$type,['has_message'=>true,'message_type'=>$type]);return $this->detail($id);});}
 public function reassign(int $id,int $v,mixed $raw):array{if($this->role()!=='admin')throw new TaskWorkflowException('Only an administrator can reassign work.');$a=$this->employee($raw);$this->version($v);return $this->mutate($id,$v,'reassigned',function(array $t)use($a){if(in_array($t['workflow_status'],['completed','cancelled'],true)||(int)$t['archived_flag'])throw new TaskWorkflowException('Closed or archived work cannot be reassigned.');return ['assignee_id'=>$a,'workflow_status'=>'assigned','status'=>'todo','responsibility'=>'employee','attention_owner_id'=>$a,'assigned_at'=>$this->now(),'acknowledged_at'=>null,'started_at'=>null,'submitted_at'=>null,'submission_summary'=>null,'correction_acknowledged_at'=>null,'approved_at'=>null,'approved_by'=>null,'approval_note'=>null,'completed_at'=>null,'cancelled_at'=>null,'archived_at'=>null,'archived_flag'=>0,'closed_reason'=>null];},['to_assignee_id'=>$a]);}
 public function revise(int $id,int $v,?string $due,?string $time,string $p):array{if($this->role()!=='admin')throw new TaskWorkflowException('Only an administrator can revise work.');$due=$this->date($due,'due');$time=$this->time($time);if(!in_array($p,['low','medium','high','urgent'],true))throw new TaskWorkflowException('Invalid priority.');return $this->mutate($id,$v,'schedule_priority_revised',function($t)use($due,$time,$p){if(in_array($t['workflow_status'],['completed','cancelled'],true)||(int)$t['archived_flag'])throw new TaskWorkflowException('Closed or archived work cannot be revised.');return ['due_date'=>$due,'due_time'=>$time,'priority'=>$p==='urgent'?'high':$p,'workflow_priority'=>$p];},['due_date'=>$due,'due_time'=>$time,'priority'=>$p]);}
 public function archive(int $id,int $v,bool $a):array{if($this->role()!=='admin')throw new TaskWorkflowException('Only an administrator can archive work.');return $this->mutate($id,$v,$a?'archived':'unarchived',function($t)use($a){if(!in_array($t['workflow_status'],['completed','cancelled'],true))throw new TaskWorkflowException('Only closed work can be archived.');return ['archived_flag'=>$a?1:0,'archived_at'=>$a?$this->now():null];});}
 private function mutate(int $id,int $v,string $type,callable $changes,array $details=[]):array{$this->version($v);return $this->atomic(function()use($id,$v,$type,$changes,$details){$old=$this->task($id);if((int)$old['version']!==$v)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');$set=$changes($old)+['updated_at'=>$this->now(),'last_activity_at'=>$this->now(),'version'=>$v+1];$p=[];$vals=[];foreach($set as $k=>$x){$p[]="$k=?";$vals[]=$x;}$vals[]=$id;$vals[]=$v;$s=$this->db->prepare('UPDATE portal_tasks SET '.implode(',',$p).' WHERE id=? AND version=?');$s->execute($vals);if($s->rowCount()!==1)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');$new=$this->task($id);$this->event($old,$new,$type,$details);return $this->detail($id);});}
 public function upload(int $id,int $v,array $file):array{$this->version($v);return $this->atomic(function()use($id,$v,$file){$old=$this->task($id);$this->authorize($old);if((int)$old['version']!==$v)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');if(in_array($old['workflow_status'],['completed','cancelled'],true)||(int)$old['archived_flag'])throw new TaskWorkflowException('Closed or archived work cannot receive uploads.');$a=$this->storeAttachment($id,null,$file);$n=$this->now();$s=$this->db->prepare('UPDATE portal_tasks SET version=version+1,updated_at=?,last_activity_at=? WHERE id=? AND version=?');$s->execute([$n,$n,$id,$v]);if($s->rowCount()!==1)throw new TaskWorkflowConflict('Someone updated this task. Reload and try again.');$new=$this->task($id);$this->event($old,$new,'proof_uploaded',['attachment_id'=>$a]);return $this->detail($id);});}
 private function storeAttachment(int $id,?int $mid,array $f):int{if(($f['error']??0)!==UPLOAD_ERR_OK||(!is_uploaded_file((string)($f['tmp_name']??''))&&empty($f['_test'])))throw new TaskWorkflowException('Invalid attachment upload.');$size=(int)($f['size']??0);if($size<1||$size>10485760)throw new TaskWorkflowException('Attachments must be between 1 byte and 10 MB.');$name=basename((string)($f['name']??''));$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp','txt'=>'text/plain'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$f['tmp_name']);if(($allowed[$ext]??null)!==$mime)throw new TaskWorkflowException('Unsupported or mismatched attachment type.');if(!is_dir($this->storageDir)&&!mkdir($this->storageDir,0770,true)&&!is_dir($this->storageDir))throw new TaskWorkflowException('Protected storage is unavailable.');$key=bin2hex(random_bytes(24)).'.'.$ext;$dest=$this->storageDir.'/'.$key;$ok=!empty($f['_test'])?copy($f['tmp_name'],$dest):move_uploaded_file($f['tmp_name'],$dest);if(!$ok)throw new TaskWorkflowException('Attachment could not be stored.');$this->createdFiles[]=$dest;try{$s=$this->db->prepare('INSERT INTO task_attachments(task_id,message_id,uploaded_by,storage_key,original_name,media_type,byte_size,sha256,created_at) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$id,$mid,$this->actorId(),$key,$name,$mime,$size,hash_file('sha256',$dest),$this->now()]);}catch(Throwable $e){@unlink($dest);throw $e;}return (int)$this->db->lastInsertId();}
 private function next(array $t,string $now):void{if($t['frequency_type']==='once')return;$exists=$this->db->prepare('SELECT task_id FROM task_occurrences WHERE parent_task_id=?');$exists->execute([$t['id']]);if($exists->fetchColumn())return;$o=$this->occurrence((int)$t['id']);$scheduled=(string)($o['scheduled_for']?:$t['due_date']?:substr($now,0,10));$businessDate=substr($now,0,10);$anchor=max($scheduled,$businessDate);$due=compute_next_due_date($t['frequency_type'],$anchor,(int)$t['custom_every_n_days']);$num=(int)$o['occurrence_number']+1;$s=$this->db->prepare("INSERT INTO portal_tasks(title,description,status,priority,workflow_priority,assignee_id,created_at,updated_at,assigned_at,expected_outcome,category,linked_entity_type,linked_entity_id,start_date,due_date,due_time,frequency_type,custom_every_n_days,proof_required,workflow_status,responsibility,attention_owner_id,last_activity_at,parent_task_id,recurrence_series_id,created_by,official_flag) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)");$s->execute([$t['title'],$t['description'],'todo',$t['priority'],$t['workflow_priority'],$t['assignee_id'],$now,$now,$now,$t['expected_outcome'],$t['category'],$t['linked_entity_type'],$t['linked_entity_id'],$due,$due,$t['due_time'],$t['frequency_type'],$t['custom_every_n_days'],$t['proof_required'],'assigned','employee',$t['assignee_id'],$now,$t['id'],$t['recurrence_series_id'],$t['created_by']]);$id=(int)$this->db->lastInsertId();$this->db->prepare('INSERT INTO task_occurrences(task_id,series_id,parent_task_id,occurrence_number,scheduled_for,created_at) VALUES(?,?,?,?,?,?)')->execute([$id,$t['recurrence_series_id'],$t['id'],$num,$due,$now]);$new=$this->task($id);$this->event($t,$new,'recurrence_created',['source_task_id'=>(int)$t['id'],'scheduled_for'=>$due]);}
 public function detail(int $id):array{$t=$this->task($id);$this->authorize($t);$queries=['messages'=>'SELECT m.*,u.full_name actor_name FROM task_messages m JOIN users u ON u.id=m.author_id WHERE m.task_id=?','events'=>'SELECT e.*,u.full_name actor_name FROM task_events e LEFT JOIN users u ON u.id=e.actor_id WHERE e.task_id=?','attachments'=>'SELECT a.*,u.full_name actor_name FROM task_attachments a LEFT JOIN users u ON u.id=a.uploaded_by WHERE a.task_id=?'];foreach($queries as $k=>$q){$s=$this->db->prepare($q);$s->execute([$id]);$t[$k]=$s->fetchAll(PDO::FETCH_ASSOC);}$t['occurrence']=$this->occurrence($id);$timeline=[];foreach($t['events'] as $x)$timeline[]=['kind'=>'event','id'=>(int)$x['id'],'created_at'=>$x['created_at'],'actor_name'=>$x['actor_name']??'System','label'=>ucwords(str_replace('_',' ',$x['event_type'])),'details'=>json_decode($x['event_data'],true)];foreach($t['messages'] as $x)$timeline[]=['kind'=>'message','id'=>(int)$x['id'],'created_at'=>$x['created_at'],'actor_name'=>$x['actor_name'],'label'=>ucwords(str_replace('_',' ',$x['message_type'])),'body'=>$x['body']];foreach($t['attachments'] as $x)$timeline[]=['kind'=>'attachment','id'=>(int)$x['id'],'created_at'=>$x['created_at'],'actor_name'=>$x['actor_name'],'label'=>'Proof file uploaded','attachment'=>$x];$rank=['event'=>0,'message'=>1,'attachment'=>2];usort($timeline,fn($a,$b)=>[$a['created_at'],$rank[$a['kind']],$a['id']]<=>[$b['created_at'],$rank[$b['kind']],$b['id']]);$t['timeline']=$timeline;$t['allowed_actions']=$this->allowedActions($t);return $t;}
 public function attachment(int $aid):array{$s=$this->db->prepare('SELECT a.*,t.assignee_id FROM task_attachments a JOIN portal_tasks t ON t.id=a.task_id WHERE a.id=?');$s->execute([$aid]);$a=$s->fetch(PDO::FETCH_ASSOC);if(!$a)throw new TaskWorkflowException('Attachment not found.');if($this->role()==='employee'&&(int)$a['assignee_id']!==$this->actorId())throw new TaskWorkflowException('Attachment access denied.');if(!preg_match('/^[a-f0-9]{48}\.(pdf|png|jpg|jpeg|webp|txt)$/',$a['storage_key']))throw new TaskWorkflowException('Invalid attachment key.');$real=realpath($this->storageDir.'/'.$a['storage_key']);$base=realpath($this->storageDir);if(!$real||!$base||!str_starts_with($real,$base.DIRECTORY_SEPARATOR))throw new TaskWorkflowException('Attachment is unavailable.');$a['path']=$real;return $a;}
}
